style.css:
@-moz-document domain("youtube.com") {
/* Fondo general */
    body, ytd-app, #page-manager, ytd-page-manager {
        background-color: #ccefff !important; /* celeste pastel */
    }

    /* Cabecera (barra superior donde está el logo y búsqueda) */
    ytd-masthead, #container.ytd-masthead {
        background-color: #aee4ff !important; /* un celeste más intenso */
    }

    /* Menú lateral */
    ytd-guide-renderer, #guide-content {
        background-color: #bdefff !important;
    }

    /* Cuadros de los videos */
    ytd-rich-grid-media, ytd-video-renderer, ytd-compact-video-renderer {
        background-color: #e6f9ff !important;
        border-radius: 12px !important;
        padding: 6px !important;
    }

    /* Títulos de los videos */
    #video-title {
        color: #003344 !important; /* azul oscuro para contraste */
    }

    /* Texto general */
    yt-formatted-string, span, #author-text {
        color: #002233 !important;
    }

    /* Botones (suscribirse, me gusta, etc) */
    .ytd-subscribe-button-renderer, .yt-spec-button-shape-next {
        background-color: #99ddff !important;
        border-radius: 12px !important;
        color: #002233 !important;
    }

    /* Barra de búsqueda */
    #search-form, #search-input {
        background-color: #e6f9ff !important;
        border-radius: 20px !important;
    }

    /* Comentarios */
    ytd-comment-thread-renderer, ytd-comment-renderer {
        background-color: #f2fcff !important;
        border-radius: 10px !important;
        padding: 5px !important;
    }
}
